"use strict";

// The same defect on a class EXPRESSION rather than a declaration. The
// heritage expression of a class expression is evaluated when the
// expression is evaluated, which here is while executing the variable
// declaration that holds it -- the same module-evaluation moment.
//
// The class is anonymous and its body is empty, so there is no element,
// no name, and no static token anywhere in the construct: heritage is the
// only thing that runs.
function dangerousOp(input) {
  return require("./danger").explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("fast mode is not supported here");
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  const Mode = class extends bail() {};
  void Mode;
}

module.exports = safeOp;
